"""Authored remaining Python and Backend skills; no learner code runs at import.

Examples explain a concept; the separate practice asks for a different result.
All answers, explanations and reference solutions are server-side content.
"""
from __future__ import annotations


def topic(skill, title, prerequisite, theory, example, output, question, choices,
          explanations, practice, solution, public, hidden, output_distractors,
          *, phase=None, minutes=20):
    lesson_id = skill.split(".", 1)[1].replace("_", "-") + "-v1"
    return dict(skill=skill, title=title, prerequisite=prerequisite, theory=theory,
                example=example, output=output, question=question, choices=choices,
                explanations=explanations, practice=practice, solution=solution,
                public=public, hidden=hidden, output_distractors=output_distractors,
                phase=phase, minutes=minutes, lesson_id=lesson_id)


