def build_topic(row, ordinal):
    # Positions vary across the authored catalog; the API also randomizes within
    # the server-owned session without changing the immutable answer key.
    choices = list(row["choices"])
    correct = choices[0]
    explanations = dict(zip(choices, row["explanations"]))
    shift = ordinal % len(choices)
    choices = choices[shift:] + choices[:shift]
    lesson_id = row["lesson_id"]
    practice = row["practice"]
    lesson = {
        "id": lesson_id, "title": row["title"], "skill_id": row["skill"],
        "prerequisites": row["prerequisite"], "difficulty": 5 if row["skill"].startswith("python.") else 4,
        "minutes": row["minutes"], "goal": "Применить и объяснить: " + row["title"].lower() + ".",
        "theory": row["theory"], "example": row["example"], "example_output": row["output"],
        "checkpoint": {"prompt": row["question"], "choices": choices},
        "misconception_check": {"misconception": row["choices"][1], "prompt": "Объясните ошибку в этом утверждении и сформулируйте корректное правило."},
        "practice": practice, "conclusion": row["explanations"][0],
        "question": row["question"], "choices": choices, "answer": correct,
    }
    if row["phase"] is not None: lesson["phase"] = row["phase"]
    lesson["body"] = (f"Цель: {lesson['goal']}\nПеред началом: " + ", ".join(row["prerequisite"]) +
                      f"\n\nТеория: {row['theory']}\n\nCheckpoint: {row['question']}\n\nПрактика: {practice}\n\nВывод: {lesson['conclusion']}")
    prediction_choices = [row["output"], *row["output_distractors"]]
    prediction_shift = (ordinal + 1) % 3
    prediction_choices = prediction_choices[prediction_shift:] + prediction_choices[:prediction_shift]
    checks = (
        {"id": lesson_id + "-concept", "prompt": row["question"], "choices": choices,
         "answer": correct, "explanation": row["explanations"][0], "choice_explanations": explanations},
        {"id": lesson_id + "-trace", "prompt": "Предскажите полный вывод этого фрагмента:\n" + row["example"],
         "choices": prediction_choices, "answer": row["output"],
         "explanation": "Следуйте по строкам примера с учётом правила: " + row["explanations"][0],
         "choice_explanations": {
             row["output"]: "Это точный вывод фрагмента. " + row["explanations"][0],
             row["output_distractors"][0]: "Этот вариант не учитывает состояние или порядок вызовов примера. " + row["explanations"][1],
             row["output_distractors"][1]: "Этот вариант подменяет результат другого шага. " + row["explanations"][2],
         }},
    )
    ladder = {"version": 1, "lesson_id": lesson_id, "skill_id": row["skill"], "hints": (
        (1, "direction", "Разделите условие упражнения на входные данные, требуемый результат и граничный случай."),
        (2, "concept", "Прочитайте теорию о «" + row["title"] + "» и найдите правило, которое отличает пример от неверного варианта."),
        (3, "step", "Проследите один публичный вход вручную; затем отдельно проверьте нулевое, пустое или ошибочное значение, указанное в условии."),
        (4, "pseudocode", "прочитать payload\nприменить правило темы к данным\nпроверить граничный случай\nвернуть ровно требуемый формат"),
        (5, "solution", "Эталон практики:\n" + row["solution"]),
    )}
    return lesson, checks, ladder


COMPLETION_LESSONS = tuple(build_topic(row, i)[0] for i, row in enumerate(TOPICS))
COMPLETION_CHECKS = {row["lesson_id"]: build_topic(row, i)[1] for i, row in enumerate(TOPICS)}
COMPLETION_LADDERS = {row["lesson_id"]: build_topic(row, i)[2] for i, row in enumerate(TOPICS)}
COMPLETION_CODE_SPECS = {row["lesson_id"]: row for row in TOPICS}
